+        assert_eq!(sim_frame(&b, oblique), Err(OBLIQUE_STOCK.into()));
+        let c = StockShape::Cylinder { diameter: 10.0, height: 20.0 };
+        let flipped = Location { rot: quat_from_euler(std::f64::consts::PI, 0.0, 0.0), ..at };
